package dev.halloween;
import net.fabricmc.fabric.api.client.event.lifecycle.v1.ClientTickEvents;
import net.fabricmc.fabric.api.event.lifecycle.v1.ServerTickEvents;
import net.minecraft.block.*;
import net.minecraft.entity.*;
import net.minecraft.entity.passive.VillagerEntity;
import net.minecraft.util.math.*;
/** Actual player convoy starts directly below a raised court and must climb the side stairs. */
final class ElevatedCourtChecks {
 static boolean setup,started,done,stairs;static int age,inside;static VillagerEntity guard;static MarkerEntity square;static Vec3d origin;static BlockPos cage;
 static void require(boolean b,String m){if(!b)throw new AssertionError(m);}
 static void register(){if(!Boolean.getBoolean("halloween.elevatedCourtTest"))return;ServerTickEvents.END_SERVER_TICK.register(server->{if(done)return;var w=server.getOverworld();if(w.getPlayers().isEmpty())return;var p=w.getPlayers().getFirst();try{
 if(!setup){for(int x=-2;x<=2;x++)for(int z=-2;z<=2;z++)w.setChunkForced(x,z,true);for(var e:w.getOtherEntities(null,new Box(-24,90,-24,24,130,24),e->!(e instanceof net.minecraft.server.network.ServerPlayerEntity)))e.discard();for(int x=-18;x<=18;x++)for(int z=-14;z<=14;z++){w.setBlockState(new BlockPos(x,99,z),Blocks.STONE.getDefaultState(),Block.NOTIFY_LISTENERS);for(int y=100;y<=118;y++)w.setBlockState(new BlockPos(x,y,z),Blocks.AIR.getDefaultState(),Block.NOTIFY_LISTENERS);if(x>=0&&x<=14)w.setBlockState(new BlockPos(x,111,z),Blocks.STONE_BRICKS.getDefaultState(),Block.NOTIFY_LISTENERS);}
 for(int n=0;n<12;n++)for(int z=-2;z<=2;z++)w.setBlockState(new BlockPos(-12+n,100+n,z),Blocks.STONE_BRICK_STAIRS.getDefaultState().with(StairsBlock.FACING,Direction.EAST),Block.NOTIFY_LISTENERS);
 square=new MarkerEntity(EntityType.MARKER,w);square.setPosition(8.5,112,5.5);square.addCommandTag("halloween_square");w.spawnEntity(square);var bell=new MarkerEntity(EntityType.MARKER,w);bell.setPosition(8.5,112,5.5);bell.addCommandTag("halloween_bell");w.spawnEntity(bell);cage=VillageTrials.cagePosition(w,square);require(cage.getY()==112,"court cage keeps platform Y");guard=new VillagerEntity(EntityType.VILLAGER,w);guard.setVillagerData(guard.getVillagerData().withProfession(GuardProfession.ENTRY));guard.addCommandTag("halloween_guard");guard.addCommandTag("halloween_player_guarding");guard.setPosition(cage.getX()+2.5,100,cage.getZ()-1.5);w.spawnEntity(guard);var builder=new VillagerEntity(EntityType.VILLAGER,w);builder.setVillagerData(builder.getVillagerData().withProfession(BuilderProfession.ENTRY));builder.setPosition(12.5,112,5.5);w.spawnEntity(builder);PlayerJustice.clear(p);p.changeGameMode(net.minecraft.world.GameMode.SURVIVAL);p.setInvulnerable(true);p.getAbilities().flying=false;p.sendAbilitiesUpdate();p.networkHandler.requestTeleport(guard.getX()-2,100,guard.getZ(),0,0);w.setTimeOfDay(1000);origin=guard.getEntityPos();setup=true;return;}
 if(!started){if(++age<30)return;for(String tag:java.util.List.of("halloween_player_wanted","halloween_player_custody","halloween_player_guard_"+guard.getUuidAsString(),"halloween_player_square_"+square.getUuidAsString(),"halloween_player_phase_"+w.getTime(),"halloween_player_crime_theft","halloween_player_days_1"))p.addCommandTag(tag);PlayerJustice.makeLead(w,p,guard);started=true;age=0;}
 age++;if(guard.getX()<-10&&guard.getY()>100)stairs=true;
 if(age%100==0)org.slf4j.LoggerFactory.getLogger("elevated-court-test").info("age={} guard={} player={} stairs={} cageReady={} pathIdle={}",age,guard.getEntityPos(),p.getEntityPos(),stairs,VillageTrials.cageReady(w,cage),guard.getNavigation().isIdle());
 if(p.getCommandTags().contains("halloween_player_cage_inside")){require(stairs,"convoy actually uses side stairs before capture");require(VillageTrials.atCourtLevel(guard.getEntityPos(),cage),"guard reaches court Y before hearing");require(Math.abs(p.getY()-cage.getY())<.5,"player inside upper cage");require(!PlayerJustice.leadAttached(w,p,guard),"lead removed in upper cage");require(guard.getEntityPos().distanceTo(origin)>10,"guard climbed twelve blocks");if(++inside>10){done=true;org.slf4j.LoggerFactory.getLogger("elevated-court-test").info("PASS actual player escort from beneath plaza: side stairs, upper court Y={}, no underground capture, hearing starts",cage.getY());stop();}}
 require(age<3000,"convoy stalled below elevated court");
 }catch(Throwable error){done=true;org.slf4j.LoggerFactory.getLogger("elevated-court-test").error("FAIL",error);stop();}});
 ClientTickEvents.START_CLIENT_TICK.register(c->{if(c.player==null)return;c.options.pauseOnLostFocus=false;c.options.forwardKey.setPressed(false);c.options.backKey.setPressed(false);c.options.sneakKey.setPressed(false);c.options.jumpKey.setPressed(false);if(c.currentScreen instanceof net.minecraft.client.gui.screen.GameMenuScreen)c.setScreen(null);});}
 static void stop(){net.minecraft.client.MinecraftClient.getInstance().execute(()->net.minecraft.client.MinecraftClient.getInstance().scheduleStop());}
}
